import{_ as n,o as r,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Mechanismus der Öffnung von Kultivierungsressourcen","description":"","frontmatter":{},"headers":[],"relativePath":"de/18-修炼资源开放机制.md","filePath":"de/18-修炼资源开放机制.md","lastUpdated":1789183869000}'),t={name:"de/18-修炼资源开放机制.md"};function u(a,e,d,l,h,g){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="mechanismus-der-offnung-von-kultivierungsressourcen" tabindex="-1">Mechanismus der Öffnung von Kultivierungsressourcen <a class="header-anchor" href="#mechanismus-der-offnung-von-kultivierungsressourcen" aria-label="Permalink to &quot;Mechanismus der Öffnung von Kultivierungsressourcen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>18</td></tr><tr><td>Modul</td><td>Kosmische Gesetze und Kultivierungssysteme</td></tr><tr><td>Schlüsselwörter</td><td>Ressourcenöffnung, Kultivierungsressourcen, Verteilungsmechanismus, Kartellverbot, Ressourcengerechtigkeit</td></tr></tbody></table><h2 id="i-hintergrund-und-bedeutung-des-mechanismus-der-offnung-von-kultivierungsressourcen" tabindex="-1">I. Hintergrund und Bedeutung des Mechanismus der Öffnung von Kultivierungsressourcen <a class="header-anchor" href="#i-hintergrund-und-bedeutung-des-mechanismus-der-offnung-von-kultivierungsressourcen" aria-label="Permalink to &quot;I. Hintergrund und Bedeutung des Mechanismus der Öffnung von Kultivierungsressourcen&quot;">​</a></h2><p>Im Zeitalter des Plünderungsdenkens waren Kultivierungsressourcen das zentralste Streitobjekt. Geistige Adern, Heilkräuterfelder, Energieerzadern, himmlische Schätze, geheime Kultivierungsreiche und andere Ressourcen wurden von wenigen Mächtigen und Sekten monopolisiert, und die Massen an der Basis konnten kaum formelle Kultivierungsressourcen erhalten. Dieses Ressourcenmonopol verursachte nicht nur eine schwere starre Schichtung, sondern führte auch zu unzähligen Kriegen und Massakern, die durch Ressourcenstreitigkeiten ausgelöst wurden. Das Ressourcenmonopol ist die wirtschaftliche Grundlage des Plünderungssystems — solange Ressourcen von wenigen monopolisiert werden, kann „jeder hat einen Weg&quot; nur ein leeres Wort sein.</p><p>Nach der Gründung der Anker-Symbiotischen Zivilisation wurde die „Öffnung von Kultivierungsressourcen&quot; als eine der zentralsten institutionellen Veränderungen übernommen. Das Kernziel des Mechanismus der Öffnung von Kultivierungsressourcen ist: das Ressourcenmonopol zu brechen, sicherzustellen, dass jedes Leben grundlegende Kultivierungsressourcen erhalten kann, und gleichzeitig durch den Verteilungsmechanismus „mehr Arbeit, mehr Gewinn&quot; die effiziente Nutzung und kontinuierliche Schaffung von Ressourcen zu fördern. Die Ressourcenöffnung bedeutet nicht „gleichmäßige Verteilung von Ressourcen&quot;, sondern „gerechter Zugang zu Ressourcen&quot; — unter der Voraussetzung der Gewährleistung grundlegender Bedürfnisse ist die Verteilung von Ressourcen an den individuellen Beitrag gebunden, und gleichzeitig ist jede Form von Ressourcenmonopol strengstens verboten.</p><p>Die Bedeutung des Mechanismus der Öffnung von Kultivierungsressourcen liegt darin: er beseitigt den Boden des Plünderungsdenkens von der wirtschaftlichen Grundlage her, liefert materielle Garantie für die wirkliche Popularisierung der dreihundert Kultivierungssysteme, liefert Ressourcenunterstützung für das soziale Ziel „jeder hat einen Weg&quot; und schafft einen gerechten Ausgangspunkt für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="ii-klassifizierung-und-einstufung-von-kultivierungsressourcen" tabindex="-1">II. Klassifizierung und Einstufung von Kultivierungsressourcen <a class="header-anchor" href="#ii-klassifizierung-und-einstufung-von-kultivierungsressourcen" aria-label="Permalink to &quot;II. Klassifizierung und Einstufung von Kultivierungsressourcen&quot;">​</a></h2><h3 id="_2-1-ressourcenklassifizierung" tabindex="-1">2.1 Ressourcenklassifizierung <a class="header-anchor" href="#_2-1-ressourcenklassifizierung" aria-label="Permalink to &quot;2.1 Ressourcenklassifizierung&quot;">​</a></h3><p>Die Kultivierungsressourcen im Heng Yuan Zhou werden nach Art und Verwendung in folgende Hauptkategorien unterteilt:</p><table tabindex="0"><thead><tr><th>Ressourcenkategorie</th><th>Spezifischer Inhalt</th><th>Hauptverwendung</th></tr></thead><tbody><tr><td>Energieressourcen</td><td>Geistige Adern, Energieerzadern, Geistige-Energie-Kristalle, Ursprungsenergiefragmente usw.</td><td>Bereitstellung des für die Kultivierung benötigten Energieeintrags</td></tr><tr><td>Medizinalressourcen</td><td>Geistige Kräuter, Unsterbliche Pflanzen, Pillenraffinationsmaterialien, fertige Pillen usw.</td><td>Unterstützung der Kultivierung, Behandlung von Verletzungen, Durchbrechen von Engpässen</td></tr><tr><td>Ausrüstungsressourcen</td><td>Kultivierungsartefakte, Gesetzesinstrumente, Verdopplungsvorrichtungen, Raumausrüstung usw.</td><td>Verbesserung der Kultivierungseffizienz, Unterstützung der Gesetzessteuerung</td></tr><tr><td>Raumressourcen</td><td>Geheime Kultivierungsreiche, Geistige-Energie-Konzentrationszonen, Gesetzeswahrnehmungsräume, isolierte Räume usw.</td><td>Bereitstellung spezieller Kultivierungsumgebungen</td></tr><tr><td>Wissensressourcen</td><td>Kultivierungstechniken, Kultivierungserfahrungen, Gesetzesforschungsunterlagen, technische Dokumente usw.</td><td>Bereitstellung theoretischer und methodischer Anleitung für die Kultivierung</td></tr><tr><td>Biologische Ressourcen</td><td>Geistige Tiere, Geistige Pflanzen, Vertragsleben, Symbionten usw.</td><td>Bereitstellung von Kultivierungsunterstützung, symbiotischem Kreislauf, besonderen Fähigkeiten</td></tr><tr><td>Ebenenressourcen</td><td>Unentwickelte Ebenen, Nutzungsrechte an Ebenenkanälen, Ebenenkernfragmente usw.</td><td>Bereitstellung von großräumigem Kultivierungs- und Entwicklungsraum</td></tr></tbody></table><h3 id="_2-2-ressourceneinstufung" tabindex="-1">2.2 Ressourceneinstufung <a class="header-anchor" href="#_2-2-ressourceneinstufung" aria-label="Permalink to &quot;2.2 Ressourceneinstufung&quot;">​</a></h3><p>Alle Kultivierungsressourcen werden nach Seltenheit und Wert in fünf Stufen eingeteilt:</p><table tabindex="0"><thead><tr><th>Stufe</th><th>Name</th><th>Seltenheit</th><th>Verteilungsmethode</th></tr></thead><tbody><tr><td>Stufe 1</td><td>Gewöhnliche Ressourcen</td><td>Weit verbreitet, reichliche Reserven</td><td>Kostenlose Öffnung oder preiswerte Versorgung</td></tr><tr><td>Stufe 2</td><td>Hervorragende Ressourcen</td><td>Relativ häufig, mäßige Reserven</td><td>Grundversorgung + Beitragstausch</td></tr><tr><td>Stufe 3</td><td>Seltene Ressourcen</td><td>Relativ selten, begrenzte Reserven</td><td>Beitragstausch + Antragsgenehmigung</td></tr><tr><td>Stufe 4</td><td>Epische Ressourcen</td><td>Sehr selten, sehr geringe Reserven</td><td>Wettbewerbsverteilung + Priorität für zivilisationsebene Projekte</td></tr><tr><td>Stufe 5</td><td>Legendäre Ressourcen</td><td>Extrem selten, fast ausgestorben</td><td>Sonderverteilung durch das höchste Entscheidungsgremium der Zivilisation</td></tr></tbody></table><h2 id="iii-kernprinzipien-der-ressourcenoffnung" tabindex="-1">III. Kernprinzipien der Ressourcenöffnung <a class="header-anchor" href="#iii-kernprinzipien-der-ressourcenoffnung" aria-label="Permalink to &quot;III. Kernprinzipien der Ressourcenöffnung&quot;">​</a></h2><h3 id="_3-1-grundsicherheitsprinzip" tabindex="-1">3.1 Grundsicherheitsprinzip <a class="header-anchor" href="#_3-1-grundsicherheitsprinzip" aria-label="Permalink to &quot;3.1 Grundsicherheitsprinzip&quot;">​</a></h3><p>Jedes Leben hat das Recht, Ressourcen der Stufe 1 und 2 zu erhalten, die für die Aufrechterhaltung der grundlegenden Kultivierung erforderlich sind. Die Grundsicherheitsressourcen werden durch das „Garantiesystem, dass jeder einen Weg hat&quot; kostenlos oder preiswert versorgt, ohne Schwellen und ohne Diskriminierung. Der Standard der Grundsicherheit wird regelmäßig vom Parlament der Republik aller Rassen entsprechend der Ressourcensituation und dem Entwicklungsstadium der Zivilisation angepasst, um sicherzustellen, dass das Sicherheitsniveau mit der Tragfähigkeit der Zivilisation übereinstimmt.</p><h3 id="_3-2-prinzip-von-mehr-arbeit-mehr-gewinn" tabindex="-1">3.2 Prinzip von mehr Arbeit, mehr Gewinn <a class="header-anchor" href="#_3-2-prinzip-von-mehr-arbeit-mehr-gewinn" aria-label="Permalink to &quot;3.2 Prinzip von mehr Arbeit, mehr Gewinn&quot;">​</a></h3><p>Über die Grundsicherheit hinaus basiert die Verteilung von Ressourcen der Stufe 3 und höher hauptsächlich auf dem Beitragswert des Individuums zum symbiotischen Netzwerk. Je größer der Beitrag, desto mehr Ressourcen können getauscht werden und desto höher ist die Stufe. Das Prinzip von mehr Arbeit, mehr Gewinn ermutigt die Kultivierenden, sich bemühen, ihr eigenes Reich zu erhöhen und größere Beiträge zur Zivilisation zu leisten, und stellt gleichzeitig sicher, dass Ressourcen zu den Individuen und Gruppen fließen, die sie am effizientesten nutzen können.</p><h3 id="_3-3-kartellverbotsprinzip" tabindex="-1">3.3 Kartellverbotsprinzip <a class="header-anchor" href="#_3-3-kartellverbotsprinzip" aria-label="Permalink to &quot;3.3 Kartellverbotsprinzip&quot;">​</a></h3><p>Es ist strengstens verboten, dass irgendein Individuum, eine Organisation oder eine Rasse Kultivierungsressourcen monopolisiert. Die spezifischen Maßnahmen gegen Kartelle umfassen:</p><ul><li>Die von einem einzelnen Individuum oder einer Organisation gehaltenen Ressourcen der Stufe 3 und höher dürfen 1% der Gesamtreserven der Zivilisation nicht überschreiten</li><li>Verbot des Hortens für Spekulation — Ressourcenhalter dürfen bei Ressourcenknappheit nicht böswillig horten und Preise hochtreiben</li><li>Verbot des ausschließlichen Besitzes — öffentliche Ressourcen (wie öffentliche geistige Adern, öffentliche geheime Reiche usw.) dürfen nicht privat exklusiv besessen werden</li><li>Verstöße gegen das Kartellverbot werden vom Anker-Gericht streng sanktioniert, einschließlich Ressourcenbeschlagnahme, Nullsetzung des Beitragswerts, Einschränkung der Kultivierungsrechte usw.</li></ul><h3 id="_3-4-prinzip-der-nachhaltigen-nutzung" tabindex="-1">3.4 Prinzip der nachhaltigen Nutzung <a class="header-anchor" href="#_3-4-prinzip-der-nachhaltigen-nutzung" aria-label="Permalink to &quot;3.4 Prinzip der nachhaltigen Nutzung&quot;">​</a></h3><p>Die Erschließung und Nutzung aller Ressourcen muss dem Prinzip der Nachhaltigkeit folgen, und räuberische Ausbeutung im Stil „den See trockenlegen, um Fische zu fangen&quot; ist nicht zulässig. Die spezifischen Anforderungen umfassen:</p><ul><li>Die Erschließungsgeschwindigkeit von Ressourcen darf die natürliche Regenerationsgeschwindigkeit der Ressourcen nicht überschreiten (für nicht erneuerbare Ressourcen müssen Alternativpläne erstellt werden)</li><li>Die Erschließung von Ressourcen muss eine Umweltverträglichkeitsprüfung durchlaufen, um irreversible Schäden am Ökosystem zu verhindern</li><li>Für gefährdete Ressourcen werden Abbauverbots- oder Abbaubeschränkungsrichtlinien umgesetzt, um die Regenerationsfähigkeit der Ressourcen zu schützen</li><li>Förderung der künstlichen Kultivierung und Synthese seltener Ressourcen durch technische Mittel (wie Gesetzesingenieurwesen, Verdopplungstechnologie usw.), um die Abhängigkeit von natürlichen Ressourcen zu verringern</li></ul><h3 id="_3-5-prinzip-der-offenheit-und-transparenz" tabindex="-1">3.5 Prinzip der Offenheit und Transparenz <a class="header-anchor" href="#_3-5-prinzip-der-offenheit-und-transparenz" aria-label="Permalink to &quot;3.5 Prinzip der Offenheit und Transparenz&quot;">​</a></h3><p>Der Verteilungsprozess von Ressourcen muss offen und transparent sein und die Aufsicht aller Leben akzeptieren:</p><ul><li>Die Reserven, Verteilung und Erschließungssituation aller öffentlichen Ressourcen werden regelmäßig der Öffentlichkeit bekannt gegeben</li><li>Die Standards, Prozesse und Ergebnisse der Ressourcenverteilung sind offen und einsehbar</li><li>Ein Berufungsmechanismus für die Ressourcenverteilung wird eingerichtet, sodass Individuen, die mit dem Verteilungsergebnis nicht einverstanden sind, eine Überprüfung beantragen können</li><li>Der „Ressourcengerechtigkeitsausschuss&quot; unter dem Anker-Gericht überwacht speziell die Gerechtigkeit und Rechtmäßigkeit der Ressourcenverteilung</li></ul><h2 id="iv-spezifische-mechanismen-der-ressourcenoffnung" tabindex="-1">IV. Spezifische Mechanismen der Ressourcenöffnung <a class="header-anchor" href="#iv-spezifische-mechanismen-der-ressourcenoffnung" aria-label="Permalink to &quot;IV. Spezifische Mechanismen der Ressourcenöffnung&quot;">​</a></h2><h3 id="_4-1-mechanismus-der-gemeinsamen-produktionsvertrage" tabindex="-1">4.1 Mechanismus der gemeinsamen Produktionsverträge <a class="header-anchor" href="#_4-1-mechanismus-der-gemeinsamen-produktionsvertrage" aria-label="Permalink to &quot;4.1 Mechanismus der gemeinsamen Produktionsverträge&quot;">​</a></h3><p>Der gemeinsame Produktionsvertrag ist die zentrale institutionelle Gestaltung der Öffnung von Kultivierungsressourcen, und seine grundlegende Betriebsweise wurde im Dokument „Prinzip der Verteilung von mehr Arbeit, mehr Gewinn&quot; detailliert beschrieben. Auf dem Gebiet der Ressourcenöffnung umfassen die spezifischen Anwendungen des gemeinsamen Produktionsvertrags:</p><ul><li><strong>Vertrag für geistige Adern</strong>: Öffentliche geistige Adern werden an Kultivierendengruppen oder Rassengemeinschaften vergeben, wobei der Vertragspartner für die Wartung und nachhaltige Erschließung der Ader verantwortlich ist und einen bestimmten Anteil an der Produktion der Ader erhält</li><li><strong>Vertrag für Heilkräuterfelder</strong>: Öffentliche Heilkräuterfelder werden an kultivierungsfähige Kultivierende vergeben, wobei der Vertragspartner für den Anbau und die Pflege der geistigen Kräuter verantwortlich ist und die Ernte anteilig verteilt wird</li><li><strong>Verwaltung geheimer Reiche</strong>: Öffentliche geheime Kultivierungsreiche werden an professionelle Teams zur Verwaltung delegiert, wobei der Verwalter für die Wartung und Sicherheit des Reiches verantwortlich ist und die Nutzer eine angemessene Nutzungsgebühr zahlen</li><li><strong>Ressourcenexploration</strong>: Kultivierende werden ermutigt, an der Exploration von Ressourcen in unentwickelten Gebieten teilzunehmen, wobei die Entdecker ein Prioritätsvertragsrecht für die neu entdeckten Ressourcen genießen</li></ul><h3 id="_4-2-mechanismus-des-beitragswerttauschs" tabindex="-1">4.2 Mechanismus des Beitragswerttauschs <a class="header-anchor" href="#_4-2-mechanismus-des-beitragswerttauschs" aria-label="Permalink to &quot;4.2 Mechanismus des Beitragswerttauschs&quot;">​</a></h3><p>Die symbiotische Zivilisation hat ein einheitliches „System des Beitragswerttauschs&quot; aufgebaut, in dem Kultivierende durch Beiträge zum symbiotischen Netzwerk Beitragswerte ansammeln und diese dann gegen verschiedene Kultivierungsressourcen eintauschen können:</p><ul><li>Die Wege zur Erlangung von Beitragswerten umfassen: Kultivierungsfortschritt, Wissensaustausch, technologische Innovation, öffentlicher Dienst, ökologische Restauration, Zivilisationsschutz usw.</li><li>Das Tauschsystem implementiert „klare Preise&quot;, jede Ressource hat einen klaren Beitragswertpreis, und der Preis wird dynamisch entsprechend der Seltenheit und Nachfrage der Ressource angepasst</li><li>Das Tauschsystem unterstützt die Funktion des „Vorschusses&quot; — vielversprechende Kultivierende können einen bestimmten Betrag an Beitragswerten für den Ressourcentausch vorschießen und in der Zukunft durch Beiträge zurückzahlen</li><li>Das Tauschsystem ist in Echtzeit mit dem Anker-Netzwerk verbunden, um die Sicherheit und Zuverlässigkeit der Aufzeichnung und des Tauschs von Beitragswerten zu gewährleisten</li></ul><h3 id="_4-3-mechanismus-der-kostenlosen-offnung-offentlicher-ressourcen" tabindex="-1">4.3 Mechanismus der kostenlosen Öffnung öffentlicher Ressourcen <a class="header-anchor" href="#_4-3-mechanismus-der-kostenlosen-offnung-offentlicher-ressourcen" aria-label="Permalink to &quot;4.3 Mechanismus der kostenlosen Öffnung öffentlicher Ressourcen&quot;">​</a></h3><p>Die folgenden Arten von Ressourcen werden allen Leben kostenlos geöffnet:</p><ul><li><strong>Wissensressourcen</strong>: Grundlegende Techniken der dreihundert Kultivierungssysteme, öffentliche Kultivierungserfahrungen, grundlegende Gesetzesforschungsunterlagen usw.</li><li><strong>Energieressourcen der Stufe 1</strong>: Grundlegende geistige Energie, gewöhnliche Energiekristalle und andere weit verbreitete niedrigstufige Energieressourcen</li><li><strong>Öffentliche Kultivierungsräume</strong>: Öffentliche Kultivierungsräume, grundlegende Gesetzeswahrnehmungsräume, gewöhnliche isolierte Räume usw.</li><li><strong>Grundlegende medizinische Ressourcen</strong>: Grundlegende Heilungstechniken, gewöhnliche verletzungsheilende Pillen, grundlegende Rehabilitationsdienste usw.</li><li><strong>Grundlegende Bildungsressourcen</strong>: Grundlegende Kultivierungskurse, Einsteiger-Mentorenanleitung, Nutzung allgemeiner Kultivierungsausrüstung usw.</li></ul><h3 id="_4-4-mechanismus-der-gezielten-verteilung-besonderer-ressourcen" tabindex="-1">4.4 Mechanismus der gezielten Verteilung besonderer Ressourcen <a class="header-anchor" href="#_4-4-mechanismus-der-gezielten-verteilung-besonderer-ressourcen" aria-label="Permalink to &quot;4.4 Mechanismus der gezielten Verteilung besonderer Ressourcen&quot;">​</a></h3><p>Für seltene Ressourcen wie die der Stufe 4 und 5 wird ein Mechanismus der „gezielten Verteilung&quot; implementiert:</p><ul><li>Seltene Ressourcen werden vorrangig an zivilisationsebene Schlüsselprojekte (wie Ankerbau, Ebenenentwicklung, technologische Durchbrüche usw.) verteilt</li><li>Für Individuen mit besonderen Bedürfnissen (wie Bedarf an bestimmten Ressourcen zum Durchbrechen eines wichtigen Reichs, Bedarf an seltenen Medikamenten zur Behandlung besonderer Verletzungen usw.) kann durch Antragsgenehmigung eine gezielte Verteilung erhalten werden</li><li>Der Verteilungsplan für seltene Ressourcen wird vom „Ressourcenverteilungsausschuss&quot; unter dem Parlament der Republik aller Rassen erstellt und nach Genehmigung durch das Parlament umgesetzt</li><li>Die Ergebnisse der gezielten Verteilung werden der Öffentlichkeit bekannt gegeben und unterliegen der Aufsicht</li></ul><h2 id="v-ressourcenschaffung-und-nachhaltige-entwicklung" tabindex="-1">V. Ressourcenschaffung und nachhaltige Entwicklung <a class="header-anchor" href="#v-ressourcenschaffung-und-nachhaltige-entwicklung" aria-label="Permalink to &quot;V. Ressourcenschaffung und nachhaltige Entwicklung&quot;">​</a></h2><p>Die Öffnung von Kultivierungsressourcen ist nicht nur „Verteilung des Bestands&quot;, sondern auch „Schaffung von Zuwachs&quot;. Die symbiotische Zivilisation fördert nachdrücklich die künstliche Schaffung und nachhaltige Erschließung von Ressourcen:</p><h3 id="_5-1-kunstliche-kultivierung-von-ressourcen" tabindex="-1">5.1 Künstliche Kultivierung von Ressourcen <a class="header-anchor" href="#_5-1-kunstliche-kultivierung-von-ressourcen" aria-label="Permalink to &quot;5.1 Künstliche Kultivierung von Ressourcen&quot;">​</a></h3><ul><li><strong>Künstlicher Anbau geistiger Kräuter</strong>: Durch Gesetzesingenieurtechnik werden verschiedene geistige Kräuter in künstlichen Umgebungen angebaut, um die Abhängigkeit von wilden geistigen Kräutern zu verringern</li><li><strong>Künstliche Energieerzeugung</strong>: Durch Technologien wie Materie-Energie-Umwandlungsvorrichtungen, Gesetzesresonanzgeneratoren usw. werden künstlich geistige Energie und Energiekristalle erzeugt</li><li><strong>Künstliche Zucht geistiger Tiere</strong>: Einrichtung von Zuchtbasen für geistige Tiere, künstliche Zucht verschiedener geistiger Tiere und Schutz der wilden Populationen geistiger Tiere</li><li><strong>Künstlicher Bau geheimer Reiche</strong>: Durch Raumgesetzestechnik werden künstlich geheime Kultivierungsreiche gebaut, um das Angebot an Kultivierungsräumen zu erhöhen</li></ul><h3 id="_5-2-kreislaufnutzung-von-ressourcen" tabindex="-1">5.2 Kreislaufnutzung von Ressourcen <a class="header-anchor" href="#_5-2-kreislaufnutzung-von-ressourcen" aria-label="Permalink to &quot;5.2 Kreislaufnutzung von Ressourcen&quot;">​</a></h3><ul><li><strong>Energierückgewinnung</strong>: Einrichtung von Energierückgewinnungssystemen, um die während der Kultivierung verlorene Energie, die im Kampf verstreute Energie usw. zurückzugewinnen und wiederzuverwenden</li><li><strong>Verarbeitung von Medikamentenrückständen</strong>: Sekundäre Extraktion und Verarbeitung von Kräuterrückständen nach der Pillenraffination, um die Verwendungsrate von Medikamentenressourcen zu erhöhen</li><li><strong>Rückgewinnung und Wiederherstellung von Ausrüstung</strong>: Rückgewinnung und Wiederherstellung entsorgter Kultivierungsausrüstung, um Materialverschwendung zu verringern</li><li><strong>Kreislaufnutzung von Räumen</strong>: Reinigung und kreislaufweise Nutzung von genutzten isolierten Räumen, temporären Kultivierungsräumen usw.</li></ul><h3 id="_5-3-ressourcenersatztechnologie" tabindex="-1">5.3 Ressourcenersatztechnologie <a class="header-anchor" href="#_5-3-ressourcenersatztechnologie" aria-label="Permalink to &quot;5.3 Ressourcenersatztechnologie&quot;">​</a></h3><ul><li>Förderung der Forschung und Entwicklung von Ersatzstoffen für seltene Ressourcen, um durch technische Mittel „seltene Materialien durch gewöhnliche Materialien zu ersetzen&quot; zu verwirklichen</li><li>Für nicht erneuerbare legendäre Ressourcen werden strenge Schutz- und Nutzungspläne erstellt, gleichzeitig wird die Investition in die Forschung und Entwicklung von Ersatztechnologien erhöht</li><li>Einrichtung eines „Fonds für Forschung und Entwicklung von Ressourcenersatztechnologie&quot; zur Finanzierung entsprechender Forschungsprojekte</li></ul><h2 id="vi-aufsicht-und-rechtsbehelfe-bei-der-ressourcenoffnung" tabindex="-1">VI. Aufsicht und Rechtsbehelfe bei der Ressourcenöffnung <a class="header-anchor" href="#vi-aufsicht-und-rechtsbehelfe-bei-der-ressourcenoffnung" aria-label="Permalink to &quot;VI. Aufsicht und Rechtsbehelfe bei der Ressourcenöffnung&quot;">​</a></h2><h3 id="_6-1-aufsichtsmechanismus" tabindex="-1">6.1 Aufsichtsmechanismus <a class="header-anchor" href="#_6-1-aufsichtsmechanismus" aria-label="Permalink to &quot;6.1 Aufsichtsmechanismus&quot;">​</a></h3><ul><li><strong>Echtzeitüberwachung durch das Anker-Netzwerk</strong>: Das Anker-Netzwerk überwacht in Echtzeit die Erschließung, Verteilung und Nutzung aller öffentlichen Ressourcen und warnt bei Auffälligkeiten rechtzeitig</li><li><strong>Ressourcengerechtigkeitsausschuss</strong>: Überwacht speziell die Gerechtigkeit und Rechtmäßigkeit der Ressourcenverteilung und nimmt Meldungen und Beschwerden entgegen</li><li><strong>Soziale Aufsicht</strong>: Förderung aller Leben, unangemessene Verhaltensweisen bei der Erschließung und Verteilung von Ressourcen zu überwachen und zu melden</li><li><strong>Regelmäßige Prüfung</strong>: Jährliche unabhängige Prüfung der Ressourcenverwaltungsorgane, wobei die Prüfergebnisse der Öffentlichkeit bekannt gegeben werden</li></ul><h3 id="_6-2-rechtsbehelfsmechanismus" tabindex="-1">6.2 Rechtsbehelfsmechanismus <a class="header-anchor" href="#_6-2-rechtsbehelfsmechanismus" aria-label="Permalink to &quot;6.2 Rechtsbehelfsmechanismus&quot;">​</a></h3><ul><li><strong>Verteilungsberufung</strong>: Individuen, die mit dem Ergebnis der Ressourcenverteilung nicht einverstanden sind, können beim Ressourcengerechtigkeitsausschuss eine Überprüfung beantragen</li><li><strong>Schiedsverfahren bei Ressourcenstreitigkeiten</strong>: Ressourcenstreitigkeiten werden vom Anker-Gericht geschlichtet, und das Schiedsergebnis hat Rechtskraft</li><li><strong>Rechtsbehelfe bei Rechtsverletzungen</strong>: Individuen, die durch Verhaltensweisen wie Ressourcenmonopol, Ressourcenplünderung usw. geschädigt wurden, können beim Anker-Gericht Klage erheben und Schadenersatz verlangen</li><li><strong>Notfallhilfe</strong>: In besonderen Situationen (wie Katastrophen, Kriegen usw.) wird ein Notfall-Ressourcenzuweisungsmechanismus aktiviert, um die grundlegenden Ressourcenbedürfnisse der betroffenen Gruppen sicherzustellen</li></ul><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Der Mechanismus der Öffnung von Kultivierungsressourcen ist der Kern des Wirtschaftssystems der Anker-Symbiotischen Zivilisation. Durch die fünf Prinzipien „Grundsicherheit + mehr Arbeit, mehr Gewinn + Kartellverbot + Nachhaltigkeit + Offenheit und Transparenz&quot; baut er ein gerechtes, effizientes und nachhaltiges Ressourcenverteilungssystem auf. Das ultimative Ziel des Mechanismus der Ressourcenöffnung ist nicht, alle Leben die gleiche Menge an Ressourcen erhalten zu lassen, sondern jedem Leben eine gerechte Chance auf Zugang zu Ressourcen zu geben, Ressourcen dorthin fließen zu lassen, wo sie am meisten Wert schaffen können, und die Gesamtmenge der Ressourcen der Zivilisation unter der Voraussetzung der Nachhaltigkeit kontinuierlich wachsen zu lassen. Wenn Kultivierungsressourcen nicht mehr das von wenigen monopolierte Privateigentum sind, sondern der von allen Rassen geteilte, im Kreislauf zunehmende öffentliche Reichtum, dann kann das Ideal „jeder hat einen Weg&quot; wirklich verwirklicht werden, und das Ziel des gemeinsamen Fortschritts aller Rassen kann wirklich erreicht werden.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Prinzip der Verteilung von mehr Arbeit, mehr Gewinn)</li><li>08-人人有路保障体系 (Garantiesystem, dass jeder einen Weg hat)</li><li>22-资源分配联产承包机制 (Mechanismus der gemeinsamen Produktionsverträge für die Ressourcenverteilung)</li></ul>',57)])])}const f=n(t,[["render",u]]);export{c as __pageData,f as default};
